<?php
if(!defined('SCHOOLOS_EXPERIENCE')){http_response_code(404);exit;}
function af_ready():bool{return xp_has('af_settings');}
function af_setting(string $key,string $default=''):string{if($default==='')$default=['legal_name'=>'Vendorhub Global Concept','contact_email'=>'admin@getschoolos.com.ng'][$key]??'';if(!af_ready())return $default;$value=q('SELECT value FROM af_settings WHERE name=?',[$key])->fetchColumn();return $value===false?$default:(string)$value;}
function af_write(string $key,string $value):void{q('INSERT INTO af_settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$key,$value]);}
function af_install(array $u):void{af_authorize($u,true);global $pdo;foreach([
'CREATE TABLE IF NOT EXISTS af_settings(name VARCHAR(60) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
"CREATE TABLE IF NOT EXISTS af_accounts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,code CHAR(32) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'pending',terms_at DATETIME NOT NULL,bank_code VARCHAR(20) NULL,account_number VARCHAR(20) NULL,account_name VARCHAR(180) NULL,recipient VARCHAR(100) NULL,recipient_environment VARCHAR(8) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
'CREATE TABLE IF NOT EXISTS af_referrals(tenant_id BIGINT UNSIGNED PRIMARY KEY,affiliate_id BIGINT UNSIGNED NOT NULL,rate_bps INT NOT NULL,hold_days INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(affiliate_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
"CREATE TABLE IF NOT EXISTS af_credits(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,affiliate_id BIGINT UNSIGNED NOT NULL,payment_id BIGINT UNSIGNED NULL UNIQUE,source_transaction_id BIGINT UNSIGNED NULL UNIQUE,source_reference VARCHAR(120) NULL UNIQUE,environment VARCHAR(8) NOT NULL DEFAULT 'test',gross_kobo BIGINT NOT NULL,amount_kobo BIGINT NOT NULL,reversed_kobo BIGINT NOT NULL DEFAULT 0,refunded_kobo BIGINT NOT NULL DEFAULT 0,available_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(affiliate_id,available_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS af_withdrawals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,affiliate_id BIGINT UNSIGNED NOT NULL,amount_kobo BIGINT NOT NULL,reference VARCHAR(100) NOT NULL UNIQUE,recipient VARCHAR(100) NOT NULL,account_label VARCHAR(240) NOT NULL,environment VARCHAR(8) NOT NULL DEFAULT 'test',status VARCHAR(20) NOT NULL DEFAULT 'requested',provider_code VARCHAR(100) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(affiliate_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
'CREATE TABLE IF NOT EXISTS af_events(event_key VARCHAR(140) PRIMARY KEY,details VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'
] as $sql)$pdo->exec($sql);foreach(['enabled'=>'0','rate_bps'=>'0','hold_days'=>'30','min_kobo'=>'500000','legal_name'=>'Vendorhub Global Concept','contact_email'=>'admin@getschoolos.com.ng'] as $k=>$v)if(!g('SELECT COUNT(*) FROM af_settings WHERE name=?',[$k]))af_write($k,$v);audit('affiliate.install');}
function af_authorize(array $u,bool $admin=false):void{if(defined('SCHOOLOS_DEMO_MODE'))throw new RuntimeException('Affiliate financial actions are disabled in the shared demo.');$fresh=q('SELECT * FROM users WHERE id=? AND active=1',[$u['id']])->fetch();if(!$fresh||$fresh['role']!==$u['role']||$fresh['tenant_id']!=$u['tenant_id']||($admin&&$fresh['role']!=='platform_super_admin'))throw new RuntimeException('Account permission denied.');}
function af_enabled():bool{return af_ready()&&af_setting('enabled')==='1';}
function af_account(array $u,bool $approved=false):array{af_authorize($u);$a=af_ready()?q('SELECT * FROM af_accounts WHERE user_id=?',[$u['id']])->fetch():false;if(!$a||($approved&&$a['status']!=='approved'))throw new RuntimeException('An approved affiliate account is required.');return $a;}
function af_cookie(string $value,int $expiry):void{$path=str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/index.php'));$path=$path==='.'||$path==='/'?'/':rtrim($path,'/').'/';setcookie('SchoolOSReferral',$value,['expires'=>$expiry,'path'=>$path,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','httponly'=>true,'samesite'=>'Lax']);}
function af_capture():void{if(isset($_GET['clear_ref'])){af_cookie('',time()-3600);unset($_SESSION['af_referral']);return;}if(!af_enabled()||defined('SCHOOLOS_DEMO_MODE'))return;$salt=xp_setting('rate_salt');if(strlen($salt)<32)return;$prior=$_SESSION['af_referral']??null;if($prior&&$prior['expires']>=time())return;unset($_SESSION['af_referral']);$token=$_COOKIE['SchoolOSReferral']??'';if(is_string($token)){ $bits=explode('.',$token);if(count($bits)===3&&preg_match('/^[a-f0-9]{32}$/D',$bits[0])&&ctype_digit($bits[1])&&(int)$bits[1]>=time()&&(int)$bits[1]<=time()+30*86400&&hash_equals(hash_hmac('sha256',$bits[0].'.'.$bits[1],$salt),$bits[2])){$_SESSION['af_referral']=['code'=>$bits[0],'expires'=>(int)$bits[1]];return;}}$code=$_GET['ref']??'';if(!is_string($code)||!preg_match('/^[a-f0-9]{32}$/D',$code))return;$a=q("SELECT id FROM af_accounts WHERE code=? AND status='approved'",[$code])->fetch();if(!$a)return;$expires=time()+30*86400;$_SESSION['af_referral']=['code'=>$code,'expires'=>$expires];$payload=$code.'.'.$expires;af_cookie($payload.'.'.hash_hmac('sha256',$payload,$salt),$expires);}
// Called inside school creation's transaction. Rates are frozen at attribution, not supplied by the browser.
function af_attribute(int $tenant,int $owner,string $email):void{if(!af_enabled()||defined('SCHOOLOS_DEMO_MODE'))return;$r=$_SESSION['af_referral']??null;if(!$r||$r['expires']<time())return;$a=q("SELECT a.*,u.email,u.active FROM af_accounts a JOIN users u ON u.id=a.user_id WHERE a.code=? AND a.status='approved' FOR UPDATE",[$r['code']])->fetch();if(!$a||!$a['active']||(int)$a['user_id']===$owner||strcasecmp($a['email'],$email)===0)return;$rate=(int)af_setting('rate_bps');if($rate<1||$rate>5000)return;q('INSERT INTO af_referrals(tenant_id,affiliate_id,rate_bps,hold_days) VALUES(?,?,?,?)',[$tenant,$a['id'],$rate,(int)af_setting('hold_days','30')]);}
// Caller holds the verified xp_payment lock and transaction. One credit per source payment.
function af_credit(int $payment,string $domain):void{if(!af_ready()||defined('SCHOOLOS_DEMO_MODE'))return;$p=q("SELECT * FROM xp_payments WHERE id=? AND status='success'",[$payment])->fetch();if($p)af_credit_transaction((int)$p['transaction_id'],$payment,$domain);}
function af_credit_transaction(int $transaction,?int $payment=null,string $domain=''):void{if(!af_ready()||defined('SCHOOLOS_DEMO_MODE'))return;$p=q("SELECT * FROM saas_transactions WHERE id=? AND status='success'",[$transaction])->fetch();if(!$p)return;$r=q('SELECT * FROM af_referrals WHERE tenant_id=?',[$p['tenant_id']])->fetch();if(!$r)return;if(!in_array($domain,['test','live'],true)||$domain!==v24mode())throw new RuntimeException('Commission payment environment is not verified.');$a=q('SELECT id FROM af_accounts WHERE id=? FOR UPDATE',[$r['affiliate_id']])->fetch();if(!$a)return;$gross=(int)round((float)$p['amount']*100);if($gross<1||$gross>intdiv(PHP_INT_MAX,max(1,(int)$r['rate_bps'])))throw new RuntimeException('Commission source amount is outside supported limits.');$amount=intdiv($gross*(int)$r['rate_bps'],10000);if($amount<1)return;q('INSERT IGNORE INTO af_credits(affiliate_id,payment_id,source_transaction_id,source_reference,environment,gross_kobo,amount_kobo,available_at) VALUES(?,?,?,?,?,?,?,?)',[$a['id'],$payment,$transaction,$p['reference'],$domain,$gross,$amount,date('Y-m-d H:i:s',time()+(int)$r['hold_days']*86400)]);}
function af_balance(int $id):array{$mode=v24mode();$earned=(int)g('SELECT COALESCE(SUM(amount_kobo-reversed_kobo),0) FROM af_credits WHERE affiliate_id=? AND environment=?',[$id,$mode]);$mature=(int)g('SELECT COALESCE(SUM(amount_kobo-reversed_kobo),0) FROM af_credits WHERE affiliate_id=? AND environment=? AND available_at<=NOW()',[$id,$mode]);$reserved=(int)g("SELECT COALESCE(SUM(amount_kobo),0) FROM af_withdrawals WHERE affiliate_id=? AND environment=? AND status IN ('requested','sending','pending','success')",[$id,$mode]);return ['earned'=>$earned,'held'=>$earned-$mature,'available'=>$mature-$reserved,'reserved'=>$reserved];}
function af_withdraw(array $u,int $amount):int{if(!af_enabled())throw new RuntimeException('New withdrawals are paused. Existing balances are retained.');$a=af_account($u,true);return xp_tx(function()use($a,$amount){global $pdo;$a=q('SELECT * FROM af_accounts WHERE id=? FOR UPDATE',[$a['id']])->fetch();if($a['status']!=='approved')throw new RuntimeException('Affiliate account is not approved.');if($a['recipient_environment']!==v24mode())throw new RuntimeException('Verify a payout account in the current provider environment.');if(!$a['recipient'])throw new RuntimeException('Verify a payout account first.');$balance=af_balance((int)$a['id']);if($amount<(int)af_setting('min_kobo','500000')||$amount>$balance['available'])throw new RuntimeException('Amount is below the withdrawal minimum or exceeds available funds.');q('INSERT INTO af_withdrawals(affiliate_id,amount_kobo,reference,recipient,account_label,environment) VALUES(?,?,?,?,?,?)',[$a['id'],$amount,'af_'.bin2hex(random_bytes(20)),$a['recipient'],$a['account_name'].' · '.substr($a['account_number'],-4),v24mode()]);$id=(int)$pdo->lastInsertId();audit('affiliate.withdraw.request','withdrawal',(string)$id);return $id;});}
function af_bank(array $u,string $bank,string $number,?callable $api=null):void{if(!af_enabled())throw new RuntimeException('Affiliate program is paused.');$a=af_account($u,true);if(!preg_match('/^[0-9]{3,6}$/D',$bank)||!preg_match('/^[0-9]{10}$/D',$number))throw new RuntimeException('Enter a valid Nigerian bank code and ten-digit account number.');$api??='v23paystack';$d=$api('GET','/bank/resolve?account_number='.rawurlencode($number).'&bank_code='.rawurlencode($bank));if(($d['account_number']??'')!==$number||empty($d['account_name']))throw new RuntimeException('Provider could not verify the account.');$r=$api('POST','/transferrecipient',['type'=>'nuban','name'=>$d['account_name'],'account_number'=>$number,'bank_code'=>$bank,'currency'=>'NGN']);if(empty($r['recipient_code'])||($r['currency']??'')!=='NGN'||empty($r['active']))throw new RuntimeException('Provider did not create an active NGN recipient.');if(q("UPDATE af_accounts SET bank_code=?,account_number=?,account_name=?,recipient=?,recipient_environment=? WHERE id=? AND status='approved'",[$bank,$number,mb_substr($d['account_name'],0,180),$r['recipient_code'],v24mode(),$a['id']])->rowCount()===0&&g('SELECT status FROM af_accounts WHERE id=?',[$a['id']])!=='approved')throw new RuntimeException('Affiliate approval changed during bank verification.');audit('affiliate.bank.verified','affiliate',(string)$a['id']);}
function af_send(array $u,int $id,?callable $api=null):void{af_authorize($u,true);if(!af_enabled())throw new RuntimeException('Enable the program before initiating payouts.');$w=xp_tx(function()use($id){$w=q('SELECT * FROM af_withdrawals WHERE id=? FOR UPDATE',[$id])->fetch();if(!$w||$w['environment']!==v24mode()||$w['status']!=='requested')throw new RuntimeException('Withdrawal is already submitted or unavailable.');q('SELECT id FROM af_accounts WHERE id=? FOR UPDATE',[$w['affiliate_id']]);$a=q("SELECT a.*,u.active FROM af_accounts a JOIN users u ON u.id=a.user_id WHERE a.id=?",[$w['affiliate_id']])->fetch();if(!$a||!$a['active']||$a['status']!=='approved'||af_balance((int)$a['id'])['available']<0)throw new RuntimeException('Account is suspended or refunds have reduced its balance.');q("UPDATE af_withdrawals SET status='sending' WHERE id=?",[$id]);return $w;});$api??='v23paystack';// Unknown responses remain reserved. Never retry a transfer blindly.
$d=$api('POST','/transfer',['source'=>'balance','amount'=>(int)$w['amount_kobo'],'recipient'=>$w['recipient'],'reference'=>$w['reference'],'reason'=>'SchoolOS affiliate commission']);if(($d['reference']??'')!==$w['reference']||(int)($d['amount']??-1)!==(int)$w['amount_kobo']||($d['currency']??'')!=='NGN')throw new RuntimeException('Uncertain transfer response. Reconcile this reference; do not resubmit.');q("UPDATE af_withdrawals SET status='pending',provider_code=? WHERE id=? AND status='sending'",[$d['transfer_code']??null,$id]);audit('affiliate.payout.sent','withdrawal',(string)$id);af_reconcile($u,$id,$api);}
function af_reconcile(array $u,int $id,?callable $api=null):void{af_authorize($u,true);$w=q('SELECT * FROM af_withdrawals WHERE id=?',[$id])->fetch();if(!$w||$w['environment']!==v24mode()||!in_array($w['status'],['sending','pending','success'],true))throw new RuntimeException('No submitted transfer to reconcile.');$api??='v23paystack';$d=$api('GET','/transfer/verify/'.rawurlencode($w['reference']));if(($d['reference']??'')!==$w['reference']||(int)($d['amount']??-1)!==(int)$w['amount_kobo']||($d['currency']??'')!=='NGN'||($d['recipient']['recipient_code']??'')!==$w['recipient'])throw new RuntimeException('Transfer evidence does not match this withdrawal.');$status=$d['status']??'';if(!in_array($status,['success','failed','reversed','pending','processing','otp','received'],true))throw new RuntimeException('Unrecognized provider transfer status.');$next=in_array($status,['success','failed','reversed'],true)?$status:'pending';xp_tx(function()use($id,$next){$current=q('SELECT * FROM af_withdrawals WHERE id=? FOR UPDATE',[$id])->fetch();if($current['status']==='success'&&$next!=='reversed'){q('UPDATE af_withdrawals SET updated_at=NOW() WHERE id=?',[$id]);return;}q('UPDATE af_withdrawals SET status=?,updated_at=NOW() WHERE id=?',[$next,$id]);q('INSERT IGNORE INTO af_events(event_key,details) VALUES(?,?)',['transfer:'.$current['reference'].':'.$next,'Verified provider transfer status '.$next]);});audit('affiliate.payout.reconcile','withdrawal',$id.':'.$next);}
function af_refund(string $reference,int $refunded,string $event):void{if(!af_ready()||$refunded<1)return;xp_tx(function()use($reference,$refunded,$event){if(g('SELECT COUNT(*) FROM af_events WHERE event_key=?',[$event]))return;$c=q('SELECT * FROM af_credits WHERE source_reference=? AND environment=?',[$reference,v24mode()])->fetch();if(!$c)return;q('SELECT id FROM af_accounts WHERE id=? FOR UPDATE',[$c['affiliate_id']]);$c=q('SELECT * FROM af_credits WHERE id=? FOR UPDATE',[$c['id']])->fetch();$total=(int)$c['refunded_kobo']+min($refunded,(int)$c['gross_kobo']-(int)$c['refunded_kobo']);$target=(int)g('SELECT (CAST(? AS DECIMAL(40,0))*CAST(? AS DECIMAL(40,0))) DIV CAST(? AS DECIMAL(40,0))',[$total,$c['amount_kobo'],$c['gross_kobo']]);q('INSERT INTO af_events(event_key,details) VALUES(?,?)',[$event,'Verified refund '.$reference]);q('UPDATE af_credits SET reversed_kobo=?,refunded_kobo=? WHERE id=?',[$target,$total,$c['id']]);});}
function af_money(int $kobo):string{return '₦'.number_format($kobo/100,2);}
function af_form(string $action,string $label,array $hidden=[]):void{echo '<form method="post" class="affiliate-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="af_action" value="'.e($action).'">';foreach($hidden as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';echo '<button class="button" type="submit">'.e($label).'</button></form>';}
function af_public():void{echo '<section class="section narrow"><h2>Good introductions. Clear terms.</h2><ol class="reading"><li>Apply with your own account and accept the program terms. The platform reviews applications.</li><li>Share your personal referral link. A referral can be attributed to a newly registered school within 30 days; first attribution wins.</li><li>Eligible verified subscription payments automatically create commission records. Trials, free plans, unverified payments and self-referrals do not earn commission.</li><li>After the holding period, set up a provider-verified Nigerian bank account and request a withdrawal. Platform approval initiates the provider transfer; only server verification marks it paid.</li></ol>';if(af_enabled())echo '<div class="notice">New referral rate: '.number_format((int)af_setting('rate_bps')/100,2).'% · Holding period: '.(int)af_setting('hold_days').' days · Minimum withdrawal: '.af_money((int)af_setting('min_kobo')).'. Rate and holding terms are frozen when the school is attributed. Eligible renewals also earn commission. Refunds reverse the corresponding commission and can reduce future withdrawals.</div>';else echo '<div class="notice">The affiliate program is currently closed to new applications and referrals. Existing affiliates can sign in to view their records.</div>';echo '<p>No income is guaranteed. Do not make misleading claims, send unsolicited spam or refer accounts you control. The platform can suspend participation for abuse; existing earned balances and any disputed deductions remain visible for review.</p><a class="button" href="?page=affiliate-account">'.(me()?'Open affiliate workspace':'Apply or sign in').' →</a><p class="quiet">Program currency: NGN. Provider transfer fees and any applicable tax obligations are handled under your agreement with the operator; commission amounts displayed here exclude no undisclosed deductions.</p></section>';}
function af_action(array $u):string{af_authorize($u);xp_csrf();$action=xp_text('af_action',30);if($action==='install'){af_install($u);return 'Website & Affiliates module installed. The program is disabled until configured.';}if(!af_ready())throw new RuntimeException('Ask the platform administrator to install the module.');if($action==='settings'){af_authorize($u,true);$rate=filter_var($_POST['rate_bps']??'',FILTER_VALIDATE_INT);$hold=filter_var($_POST['hold_days']??'',FILTER_VALIDATE_INT);$min=filter_var($_POST['min_kobo']??'',FILTER_VALIDATE_INT);$email=xp_text('contact_email',190);$legal=xp_text('legal_name',180);if($rate===false||$rate<0||$rate>5000||$hold===false||$hold<0||$hold>365||$min===false||$min<100||$min>100000000||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)))throw new RuntimeException('Check rate (0–5000 basis points), hold (0–365 days), minimum (100–100000000 kobo) and email.');$enabled=isset($_POST['enabled'])?'1':'0';if($enabled==='1'&&(!$rate||!$email||!$legal||!preg_match('/^https:\/\//',xp_setting('origin'))))throw new RuntimeException('Publish your legal name, contact email, HTTPS platform origin and nonzero rate before enabling.');xp_tx(function()use($enabled,$rate,$hold,$min,$email,$legal){foreach(['enabled'=>$enabled,'rate_bps'=>(string)$rate,'hold_days'=>(string)$hold,'min_kobo'=>(string)$min,'contact_email'=>$email,'legal_name'=>$legal] as $k=>$v)af_write($k,$v);});audit('affiliate.settings');return 'Settings saved. Existing referral rates and holding periods are preserved.';}
if($action==='apply'){if(!af_enabled()||!isset($_POST['accept']))throw new RuntimeException('The program must be open and its terms accepted.');if(g('SELECT COUNT(*) FROM af_accounts WHERE user_id=?',[$u['id']]))return 'Your application is already recorded.';q('INSERT INTO af_accounts(user_id,code,terms_at) VALUES(?,?,NOW())',[$u['id'],bin2hex(random_bytes(16))]);audit('affiliate.apply');return 'Application submitted for platform review.';}
if(in_array($action,['review','send','reconcile','reject'],true)){af_authorize($u,true);$id=(int)xp_text('id',20);if($action==='review'){$status=xp_text('status',20);if(!in_array($status,['approved','rejected','suspended'],true))throw new RuntimeException('Invalid application status.');q('UPDATE af_accounts SET status=? WHERE id=?',[$status,$id]);audit('affiliate.review','affiliate',$id.':'.$status);}elseif($action==='send')af_send($u,$id);elseif($action==='reconcile')af_reconcile($u,$id);else{q("UPDATE af_withdrawals SET status='rejected' WHERE id=? AND status='requested'",[$id]);audit('affiliate.withdraw.reject','withdrawal',(string)$id);}return 'Review recorded. Check the current status below.';}
if($action==='bank'){xp_rate('affiliate-bank',5,60);af_bank($u,xp_text('bank_code',6),xp_text('account_number',10));return 'Payout account verified with the provider.';}if($action==='withdraw'){$amount=xp_text('amount',20);if(!preg_match('/^[0-9]{1,8}(\.[0-9]{1,2})?$/D',$amount))throw new RuntimeException('Enter the withdrawal amount in Naira, with up to two decimal places.');[$whole,$fraction]=array_pad(explode('.',$amount),2,'');$kobo=(int)$whole*100+(int)str_pad($fraction,2,'0');af_withdraw($u,$kobo);return 'Withdrawal requested. Funds are reserved until provider verification or rejection.';}throw new RuntimeException('Unknown affiliate action.');}
function af_dashboard():void{web_head('affiliate');echo '<section class="section narrow"><p class="eyebrow">WEBSITE & AFFILIATES</p><h1 style="font-size:48px">Your connected growth workspace.</h1><a href="?s=workspace">← Return to your SchoolOS dashboard</a>';if(isset($_SESSION['af_notice'])){echo '<div class="notice" role="status">'.e($_SESSION['af_notice']).'</div>';unset($_SESSION['af_notice']);}if(!me()){echo '<p>Already registered? <a href="?login=1">Sign in with your SchoolOS account</a>, then open Partners → Affiliate workspace. New affiliates can create a dedicated account below; this does not grant access to any school.</p>';if(af_enabled()){echo '<form method="post" class="affiliate-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="af_signup" value="1"><label>Your full name<input name="name" maxlength="150" required autocomplete="name"></label><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password (12–72 characters)<input name="password" type="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><label class="check"><input type="checkbox" name="accept" required> I accept the affiliate terms on the Partners page and the platform privacy notice.</label><button class="button">Create affiliate account</button></form>';}else echo '<p>Applications are currently closed.</p>';echo '</section>';web_foot();return;}$u=me();if(defined('SCHOOLOS_DEMO_MODE')){echo '<p>Live affiliate enrollment, banking and payouts are unavailable in the shared school demo.</p></section>';web_foot();return;}
if(isset($_SESSION['af_notice'])){echo '<div class="notice" role="status">'.e($_SESSION['af_notice']).'</div>';unset($_SESSION['af_notice']);}if($u['role']==='platform_super_admin'){af_admin($u);echo '</section>';web_foot();return;}if(!af_ready()){echo '<p>The program has not been installed.</p></section>';web_foot();return;}$a=q('SELECT * FROM af_accounts WHERE user_id=?',[$u['id']])->fetch();if(!$a){echo '<h2>Make a thoughtful introduction.</h2><p>Read the <a href="?page=affiliate">program terms and current rate</a> before applying. The school referral rate is frozen at attribution. No commission is earned for free plans, trials or unverified payments.</p>';if(af_enabled()){echo '<form method="post" class="affiliate-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="af_action" value="apply"><label class="check"><input type="checkbox" name="accept" required> I accept the published affiliate program terms.</label><button class="button">Apply to join</button></form>';}}else{$b=af_balance((int)$a['id']);echo '<div class="notice">Provider environment: '.e(strtoupper(v24mode())).'. Test commissions and withdrawals are separate from live money. Reverify your payout account after switching environments.</div><p>Application status: <b>'.e($a['status']).'</b></p><div class="metrics">';foreach(['earned'=>'Net commission','held'=>'In holding period','available'=>'Available to request','reserved'=>'Reserved / paid'] as $k=>$title)echo '<div><small>'.$title.'</small><b>'.af_money($b[$k]).'</b></div>';echo '</div>';if($a['status']==='approved'){$link=rtrim(xp_setting('origin'),'/').'/index.php?ref='.$a['code'];echo '<div class="notice"><b>Your personal referral link</b><p style="overflow-wrap:anywhere">'.e($link).'</p><small>Share this link with a school you do not own or control. The school must follow it before registering.</small></div>';echo '<details><summary>Payout account '.($a['account_name']?'· '.e($a['account_name']).' · ending '.e(substr($a['account_number'],-4)):'· not configured').'</summary><form method="post" class="affiliate-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="af_action" value="bank"><label>Nigerian bank code<input name="bank_code" inputmode="numeric" pattern="[0-9]{3,6}" required></label><p class="quiet">Use your bank’s Paystack bank code. <a href="?page=affiliate-banks">View the current bank directory →</a></p><label>Account number<input name="account_number" inputmode="numeric" pattern="[0-9]{10}" required autocomplete="off"></label><button class="button">Verify and save account</button></form></details>';echo '<details><summary>Request a withdrawal</summary><p>Minimum '.af_money((int)af_setting('min_kobo')).'. Transfers require platform review and sufficient provider balance. Changing bank details does not change an existing withdrawal’s recipient.</p><form method="post" class="affiliate-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="af_action" value="withdraw"><label>Amount in Naira<input name="amount" type="number" min="1" step="0.01" required></label><button class="button">Request withdrawal</button></form></details>';}
echo '<h2 style="font-size:30px;margin-top:35px">Referral activity</h2><div class="table-scroll"><table><tr><th>School reference</th><th>Recorded</th><th>Rate</th></tr>';foreach(q('SELECT * FROM af_referrals WHERE affiliate_id=? ORDER BY created_at DESC',[$a['id']]) as $row)echo '<tr><td>School #'.(int)$row['tenant_id'].'</td><td>'.e($row['created_at']).'</td><td>'.number_format($row['rate_bps']/100,2).'%</td></tr>';echo '</table></div><p class="quiet">School names, contacts and school records are not disclosed to affiliates.</p><h2 style="font-size:30px">Commission history</h2><div class="table-scroll"><table><tr><th>Payment reference</th><th>Commission</th><th>Reversed</th><th>Available from</th></tr>';foreach(q('SELECT * FROM af_credits WHERE affiliate_id=? ORDER BY id DESC',[$a['id']]) as $c)echo '<tr><td>Payment #'.(int)$c['payment_id'].'</td><td>'.af_money((int)$c['amount_kobo']).'</td><td>'.af_money((int)$c['reversed_kobo']).'</td><td>'.e($c['available_at']).'</td></tr>';echo '</table></div>';af_withdrawals($u,(int)$a['id']);}echo '</section>';web_foot();}
function af_admin(array $u):void{if(!af_ready()){af_form('install','Install Website & Affiliates module');return;}echo '<h2 style="font-size:30px;margin-top:30px">Program and website settings</h2><p>Disabling stops new referrals, applications, bank changes and withdrawals. Existing commission obligations remain recorded; verified payments for already attributed schools still accrue at their frozen terms. Existing transfers can still be reconciled.</p><form method="post" class="affiliate-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="af_action" value="settings"><label class="check"><input type="checkbox" name="enabled" '.(af_enabled()?'checked':'').'> Enable affiliate program</label>';foreach(['legal_name'=>'Legal operator name','contact_email'=>'Public support / privacy email','rate_bps'=>'Commission basis points (1000 = 10%, maximum 5000)','hold_days'=>'Holding period in days','min_kobo'=>'Minimum withdrawal in kobo (500000 = ₦5,000)'] as $key=>$label)echo '<label>'.e($label).'<input name="'.$key.'" value="'.e(af_setting($key)).'" '.(in_array($key,['rate_bps','hold_days','min_kobo'],true)?'type="number" required':'').'></label>';echo '<button class="button">Save settings</button></form><p>Platform HTTPS origin and Paystack credentials are configured in Setup & Accounts / Integrations. Test account resolution and transfers in Paystack test mode before enabling live payouts. Transfers that require OTP must be authorized through your provider dashboard, then reconciled here.</p><h2 style="font-size:30px;margin-top:30px">Applications and accounts</h2>';foreach(q('SELECT a.id,a.status,u.name,u.email FROM af_accounts a JOIN users u ON u.id=a.user_id ORDER BY a.id DESC') as $a){echo '<details><summary>'.e($a['name']).' · '.e($a['status']).'</summary><p>'.e($a['email']).'</p>';foreach(['approved','rejected','suspended'] as $status)af_form('review',ucfirst($status),['id'=>$a['id'],'status'=>$status]);echo '</details>';}af_withdrawals($u,null);}
function af_withdrawals(array $u,?int $affiliate):void{echo '<h2 style="font-size:30px;margin-top:35px">Withdrawals</h2><div class="table-scroll"><table><tr><th>Reference / account</th><th>Amount</th><th>Status</th><th>Action</th></tr>';$rows=$affiliate===null?q('SELECT * FROM af_withdrawals ORDER BY id DESC LIMIT 200'):q('SELECT * FROM af_withdrawals WHERE affiliate_id=? ORDER BY id DESC LIMIT 200',[$affiliate]);foreach($rows as $w){echo '<tr><td>'.e($w['reference']).'<br>'.e($w['account_label']).'</td><td>'.af_money((int)$w['amount_kobo']).'</td><td>'.e($w['status']).' · '.e($w['environment']).'</td><td>';if($u['role']==='platform_super_admin'){if($w['status']==='requested'){af_form('send','Approve & transfer',['id'=>$w['id']]);af_form('reject','Reject / release reservation',['id'=>$w['id']]);}elseif(in_array($w['status'],['sending','pending','success'],true))af_form('reconcile','Verify provider status',['id'=>$w['id']]);}echo '</td></tr>';}echo '</table></div>';}
function af_webhook():void{$raw=file_get_contents('php://input');$sig=(string)($_SERVER['HTTP_X_PAYSTACK_SIGNATURE']??'');$valid=false;foreach(array_filter([v23secret('paystack_test_secret'),v23secret('paystack_live_secret'),v23secret('paystack_secret')]) as $key)if(hash_equals(hash_hmac('sha512',$raw,$key),$sig))$valid=true;if(($_SERVER['REQUEST_METHOD']??'')!=='POST'||!$valid||defined('SCHOOLOS_DEMO_MODE')){http_response_code(401);exit;}$event=json_decode($raw,true);try{$type=$event['event']??'';$data=$event['data']??[];if($type==='charge.success'&&!empty($data['reference']))v23paymentVerify((string)$data['reference']);if(in_array($type,['transfer.success','transfer.failed','transfer.reversed'],true)&&af_ready()){$id=(int)g('SELECT id FROM af_withdrawals WHERE reference=?',[(string)($data['reference']??'')]);if($id){$admin=q("SELECT * FROM users WHERE role='platform_super_admin' AND active=1 ORDER BY id LIMIT 1")->fetch();if(!$admin)throw new RuntimeException('No active platform verifier.');af_reconcile($admin,$id);}}if($type==='refund.processed'&&af_ready()&&!empty($data['id'])){$refund=v23paystack('GET','/refund/'.rawurlencode((string)$data['id']));if(($refund['status']??'')!=='processed'||($refund['currency']??'')!=='NGN'||empty($refund['transaction']['reference']))throw new RuntimeException('Refund evidence unavailable.');af_refund((string)$refund['transaction']['reference'],(int)$refund['amount'],'refund:'.$data['id']);}}catch(Throwable $e){error_log('SchoolOS payment callback could not be reconciled.');http_response_code(500);exit;}http_response_code(200);exit;}
function af_routes():void{if(defined('SCHOOLOS_AFFILIATE_WORKER')&&PHP_SAPI==='cli'){try{if(!af_ready())throw new RuntimeException('Module is not installed.');$admin=q("SELECT * FROM users WHERE role='platform_super_admin' AND active=1 ORDER BY id LIMIT 1")->fetch();if(!$admin)throw new RuntimeException('No active platform verifier.');$failed=0;$count=0;foreach(q("SELECT id FROM af_withdrawals WHERE environment=? AND (status IN ('sending','pending') OR (status='success' AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY))) ORDER BY (status='success'),updated_at,id LIMIT 100",[v24mode()])->fetchAll() as $row){try{af_reconcile($admin,(int)$row['id']);$count++;}catch(Throwable $e){$failed++;}}echo "Affiliate reconciliation: $count verified, $failed pending investigation.\n";exit($failed?1:0);}catch(Throwable $e){fwrite(STDERR,"Affiliate reconciliation unavailable. Review module/provider configuration.\n");exit(1);}}if(isset($_GET['v23_webhook'])&&$_GET['v23_webhook']==='paystack')af_webhook();if(isset($_POST['af_signup'])){try{if(defined('SCHOOLOS_DEMO_MODE')||me()||!af_enabled())throw new RuntimeException('Affiliate registration unavailable.');xp_csrf();xp_rate('affiliate-signup',5,60);if(!isset($_POST['accept']))throw new RuntimeException('Accept the program terms.');$_POST['terms']='yes';[$name,$email,$hash]=xp_identity();xp_tx(function()use($name,$email,$hash){global $pdo;q("INSERT INTO users(tenant_id,email,password_hash,role,name,active) VALUES(NULL,?,?,'partner',?,1)",[$email,$hash,$name]);$id=(int)$pdo->lastInsertId();q('INSERT INTO af_accounts(user_id,code,terms_at) VALUES(?,?,NOW())',[$id,bin2hex(random_bytes(16))]);});$_SESSION['af_notice']='Affiliate account created. Sign in with your new details, then return here to follow your application.';}catch(Throwable $e){$_SESSION['af_notice']=$e instanceof PDOException?'Unable to create this account. If you already have an account, sign in to apply.':$e->getMessage();}header('Location:index.php?page=affiliate-account',true,303);exit;}
if(isset($_POST['af_action'])){try{if(!me())throw new RuntimeException('Sign in first.');$_SESSION['af_notice']=af_action(me());}catch(Throwable $e){$_SESSION['af_notice']=$e instanceof PDOException?'Could not complete this request. Contact platform support.':$e->getMessage();}header('Location:index.php?page=affiliate-account',true,303);exit;}
if(($_GET['page']??'')==='affiliate-account'){af_dashboard();exit;}if(($_GET['page']??'')==='affiliate-banks'){web_head('affiliate');echo '<section class="section narrow"><h1 style="font-size:44px">Nigerian bank directory</h1><a href="?page=affiliate-account">← Affiliate workspace</a>';try{if(!me())throw new RuntimeException('Sign in to view the provider directory.');af_account(me(),true);$banks=v23paystack('GET','/bank?country=nigeria&currency=NGN&perPage=100');echo '<div class="table-scroll"><table><tr><th>Bank</th><th>Code</th></tr>';foreach($banks as $bank)echo '<tr><td>'.e($bank['name']).'</td><td>'.e($bank['code']).'</td></tr>';echo '</table></div>';}catch(Throwable $e){echo '<p>Bank directory is unavailable. Ask the platform team to check its payment-provider configuration.</p>';}echo '</section>';web_foot();exit;}
if(isset($_GET['guide'])){web_guide((string)$_GET['guide']);exit;}if(isset($_GET['page'])){web_render(is_string($_GET['page'])?$_GET['page']:'invalid');exit;}}
